// Sculpted Articulated Gothic Priest/Bishop ("Ksiadz w Mitrze") exported from Blender 5.2.3 LTS (build_priest.py v4).
// Compact indexed geometry (3006 unique verts, 5608 tris) + 5000
// Poisson-disc blue-noise surface-sampled 3D micro-glyphs (zero-clump even typography!):
//   part 1  = Cassock, Pellegrina Cape, Crimson Stole & Cincture
//   part 2  = Smooth Dignified Head, White Roman Collar & Pointed Gothic Mitre + Infulae Ribbons
//   part 3  = Right Arm + Brass Gothic Cross Staff & Glowing Hexagonal Lantern
//   part 16 = Left Arm + Embossed Leather Bible
//   part 17 = Left Leg & Sculpted Boot (hip-pivoted walk stride!)
//   part 18 = Right Leg & Sculpted Boot (opposite-phase walk stride!)

const VERTS_B64 = "";
const INDICES_B64 = "";
const GLYPHS_B64 = "";

function b64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

let cachedVerts = null;
let cachedGlyphs = null;

export function getPriestMeshVerts() {
  if (cachedVerts) return cachedVerts;
  const vI16 = new Int16Array(b64ToBytes(VERTS_B64).buffer);
  const idx = new Uint16Array(b64ToBytes(INDICES_B64).buffer);
  const out = new Float32Array(idx.length * 11);
  for (let k = 0; k < idx.length; k++) {
    const vi = idx[k] * 9;
    const oi = k * 11;
    const px = vI16[vi] * 0.001, py = vI16[vi + 1] * 0.001, pz = vI16[vi + 2] * 0.001;
    out[oi + 0] = px;
    out[oi + 1] = py;
    out[oi + 2] = pz;
    out[oi + 3] = vI16[vi + 3] * 0.001;
    out[oi + 4] = vI16[vi + 4] * 0.001;
    out[oi + 5] = vI16[vi + 5] * 0.001;
    out[oi + 6] = Math.atan2(pz, px) / (Math.PI * 2) + 0.5;
    out[oi + 7] = py * 0.5;
    out[oi + 8] = vI16[vi + 6] * 0.001;
    out[oi + 9] = vI16[vi + 7] * 0.001;
    out[oi + 10] = vI16[vi + 8] * 0.001;
  }
  cachedVerts = out;
  return out;
}

export function getPriestGlyphSamples() {
  if (cachedGlyphs) return cachedGlyphs;
  const gI16 = new Int16Array(b64ToBytes(GLYPHS_B64).buffer);
  const out = new Float32Array(gI16.length);
  for (let i = 0; i < gI16.length; i++) out[i] = gI16[i] * 0.001;
  cachedGlyphs = out;
  return out;
}
